import{_ as e,o as a,c as i,a6 as s}from"./chunks/framework.CDz9-eKs.js";const p=JSON.parse('{"title":"ArchGDAL driver","description":"","frontmatter":{},"headers":[],"relativePath":"reference/archgdal.md","filePath":"reference/archgdal.md","lastUpdated":null}'),r={name:"reference/archgdal.md"};function d(n,t,l,o,h,c){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="ArchGDAL-driver" tabindex="-1">ArchGDAL driver <a class="header-anchor" href="#ArchGDAL-driver" aria-label="Permalink to &quot;ArchGDAL driver {#ArchGDAL-driver}&quot;">​</a></h1><p><code>ArchGDALDriver()</code> is the default driver. It is always available and does not require an additional package import.</p><h2 id="Extension-mappings" tabindex="-1">Extension mappings <a class="header-anchor" href="#Extension-mappings" aria-label="Permalink to &quot;Extension mappings {#Extension-mappings}&quot;">​</a></h2><p>GeoDataFrames maps these extensions to ArchGDAL/GDAL driver names:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Extension</th><th style="text-align:right;">GDAL driver</th></tr></thead><tbody><tr><td style="text-align:right;"><code>.shp</code></td><td style="text-align:right;"><code>ESRI Shapefile</code></td></tr><tr><td style="text-align:right;"><code>.gpkg</code></td><td style="text-align:right;"><code>GPKG</code></td></tr><tr><td style="text-align:right;"><code>.geojson</code></td><td style="text-align:right;"><code>GeoJSON</code></td></tr><tr><td style="text-align:right;"><code>.vrt</code></td><td style="text-align:right;"><code>VRT</code></td></tr><tr><td style="text-align:right;"><code>.sqlite</code></td><td style="text-align:right;"><code>SQLite</code></td></tr><tr><td style="text-align:right;"><code>.csv</code></td><td style="text-align:right;"><code>CSV</code></td></tr><tr><td style="text-align:right;"><code>.fgb</code></td><td style="text-align:right;"><code>FlatGeobuf</code></td></tr><tr><td style="text-align:right;"><code>.pq</code></td><td style="text-align:right;"><code>Parquet</code></td></tr><tr><td style="text-align:right;"><code>.arrow</code></td><td style="text-align:right;"><code>Arrow</code></td></tr><tr><td style="text-align:right;"><code>.gml</code></td><td style="text-align:right;"><code>GML</code></td></tr><tr><td style="text-align:right;"><code>.nc</code></td><td style="text-align:right;"><code>netCDF</code></td></tr></tbody></table><p>For other extensions, ArchGDAL performs extension-based driver detection.</p><h2 id="Reading" tabindex="-1">Reading <a class="header-anchor" href="#Reading" aria-label="Permalink to &quot;Reading {#Reading}&quot;">​</a></h2><p><code>read(ArchGDALDriver(), fn; layer, kwargs...)</code> reads the first layer by default. Set <code>layer</code> to a zero-based layer index or a layer name to select a different layer. Other keywords are passed to <a href="https://yeesian.com/ArchGDAL.jl/stable/reference/#ArchGDAL.read-Tuple%7BAbstractString%7D" target="_blank" rel="noreferrer">ArchGDAL.read</a>; use <code>options</code> for GDAL open options.</p><h2 id="Writing" tabindex="-1">Writing <a class="header-anchor" href="#Writing" aria-label="Permalink to &quot;Writing {#Writing}&quot;">​</a></h2><p><code>write(ArchGDALDriver(), fn, table; kwargs...)</code> accepts these driver keywords:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Keyword</th><th style="text-align:right;">Effect</th></tr></thead><tbody><tr><td style="text-align:right;"><code>layer_name</code></td><td style="text-align:right;">Name of the output layer; defaults to <code>&quot;data&quot;</code>.</td></tr><tr><td style="text-align:right;"><code>crs</code></td><td style="text-align:right;">Output CRS; defaults to the table CRS.</td></tr><tr><td style="text-align:right;"><code>driver</code></td><td style="text-align:right;">GDAL driver name, overriding selection from the filename.</td></tr><tr><td style="text-align:right;"><code>options</code></td><td style="text-align:right;"><code>Dict{String,String}</code> of GDAL layer-creation options.</td></tr><tr><td style="text-align:right;"><code>geometrycolumn</code></td><td style="text-align:right;">A geometry-column symbol or tuple; defaults to the table geometry columns.</td></tr><tr><td style="text-align:right;"><code>update</code></td><td style="text-align:right;">Opens an existing dataset for update instead of creating one.</td></tr></tbody></table><p>The <a href="https://yeesian.com/ArchGDAL.jl/stable/reference/" target="_blank" rel="noreferrer">ArchGDAL reference</a> and <a href="https://gdal.org/en/stable/drivers/vector/index.html" target="_blank" rel="noreferrer">GDAL vector-driver index</a> describe the supported GDAL drivers and their options.</p><h2 id="Examples" tabindex="-1">Examples <a class="header-anchor" href="#Examples" aria-label="Permalink to &quot;Examples {#Examples}&quot;">​</a></h2><h3 id="Reading-a-CSV" tabindex="-1">Reading a CSV <a class="header-anchor" href="#Reading-a-CSV" aria-label="Permalink to &quot;Reading a CSV {#Reading-a-CSV}&quot;">​</a></h3><p>Some data is distributed as CSV files with WKT geometries in a custom column such as <code>wkt</code>. Something like</p><div class="language-csv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wkt,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">name</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;POINT (30 10)&quot;,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&quot;point1&quot;</span></span></code></pre></div><p>You can read such files as follows:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GeoDataFrames</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Tell GDAL where to find the geometry column and not to keep it as a regular column (otherwise DataFrames will fail to parse it)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">df </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GeoDataFrames</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">read</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;test.csv&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, options</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GEOM_POSSIBLE_NAMES=wkt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;KEEP_GEOM_COLUMNS=NO&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span></code></pre></div><p>We don&#39;t know the CRS, so it will be <code>nothing</code> by default. You can set it using <a href="./@ref"><code>setcrs!</code></a> if you know it, but ideally we use better spatial file formats (such as Geopackage) that store the CRS natively.</p>`,19)])])}const k=e(r,[["render",d]]);export{p as __pageData,k as default};
